    for fo in FO:
        FS=[]
        for f in range(5):
            tr=fo!=f; mu=E[tr].mean(0); Xc=E-mu
            U,s,Vt=np.linalg.svd(Xc[tr],full_matrices=False)
            sv=s[:k]/np.sqrt(tr.sum())
            Z=Xc@Vt[:k].T/((sv**2+shrink*np.mean(sv**2))**0.5 if white else 1)
            R=np.sqrt(k); C=Z[tr]/np.linalg.norm(Z[tr],axis=1,keepdims=True)
            FS.append(np.concatenate([gelu(a*(Z@C.T)/R+t), rho*Z/R],1))
        for lam in lams:
